SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, LEAD(shipping_fee, 1) OVER (PARTITION BY store_id ORDER BY amount, id) AS next_shipping_fee, SUM(shipping_fee) OVER (ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_shipping_fee, FIRST_VALUE(channel, TRUE) OVER (PARTITION BY store_id ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel FROM orders;
